@pytest.mark.req("VAL-05")
def test_no_private_data_in_the_validation_site():
    """No file under site/validation/ contains the home directory, a /Users/ path, or an email address.
    Test sources, failure messages and the review log are published, so this is checked on the output."""
    email = re.compile(r"[\w.+-]+@[\w-]+\.[A-Za-z]{2,}")
    for p in (SITE / "validation").rglob("*"):
        if p.is_file():
            text = p.read_text(encoding="utf-8")
            assert str(Path.home()) not in text and "/Users/" not in text, p.name
            assert not email.search(text), (p.name, email.search(text).group())
